create or replace function public.get_organization_storage_bytes(p_organization_id uuid default null) returns bigint language sql stable security definer set search_path = public as $$ select coalesce(sum(coalesce(a.size_bytes, a.file_size, 0))::bigint, 0) from public.attachments a where a.firm_id = coalesce(p_organization_id, public.my_firm_id()) and coalesce(a.is_deleted, false) = false; $$; revoke all on function public.get_organization_storage_bytes(uuid) from public, anon; grant execute on function public.get_organization_storage_bytes(uuid) to authenticated, service_role; create or replace function public.check_storage_limit(p_additional_bytes bigint default 0) returns boolean language plpgsql stable security definer set search_path = public as $$ declare v_org_id uuid := public.my_firm_id(); v_limit bigint; v_used bigint; begin if v_org_id is null or public.is_saas_admin() then return true; end if; select pp.storage_limit_bytes into v_limit from public.organization_subscriptions os join public.platform_plans pp on pp.id = os.plan_id where os.organization_id = v_org_id and os.status in ('trial', 'active', 'past_due'); if v_limit is null then return true; end if; v_used := public.get_organization_storage_bytes(v_org_id); return v_used + coalesce(p_additional_bytes, 0) <= v_limit; end; $$; revoke all on function public.check_storage_limit(bigint) from public, anon; grant execute on function public.check_storage_limit(bigint) to authenticated, service_role; create or replace function public.assert_storage_limit(p_additional_bytes bigint default 0) returns void language plpgsql security definer set search_path = public as $$ begin if not public.check_storage_limit(p_additional_bytes) then raise exception 'plan storage limit exceeded' using errcode = '42501'; end if; end; $$; revoke all on function public.assert_storage_limit(bigint) from public, anon; grant execute on function public.assert_storage_limit(bigint) to authenticated, service_role; create or replace function public.trg_enforce_storage_limit() returns trigger language plpgsql security definer set search_path = public as $$ begin perform public.assert_storage_limit(coalesce(new.size_bytes, new.file_size, 0)::bigint); return new; end; $$; drop trigger if exists enforce_storage_limit on public.attachments; create trigger enforce_storage_limit before insert on public.attachments for each row execute function public.trg_enforce_storage_limit();
